def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    desperate_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 90:
                    aggressive_count += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = 22.0 + 18.0 * scarcity

    if aggressive_count >= 2:
        base -= 6.0
    elif aggressive_count == 1:
        base -= 2.0

    if desperate_opp >= 2:
        base += 6.0
    elif desperate_opp == 1:
        base += 3.0

    if hp <= 2:
        base = max(base, 92.0 + 10.0 * scarcity)
    elif no_water_days >= 2:
        base = max(base, 80.0 + 8.0 * scarcity)
    elif hp <= 4 or no_water_days == 1:
        base = max(base, 52.0 + 10.0 * scarcity)

    if highest_prev >= 125:
        if hp >= 5 and no_water_days == 0:
            base = min(base, 28.0 + 8.0 * scarcity)
        else:
            base = max(base, 96.0)
    elif highest_prev >= 90:
        if hp >= 6 and no_water_days == 0:
            base = min(base, 34.0 + 10.0 * scarcity)
        else:
            base = max(base, 72.0)
    elif highest_prev > 0:
        target = highest_prev + 2.0
        if target > base and target <= 78.0:
            base = target
        elif highest_prev < 45.0:
            base = max(base, 36.0)

    if day >= 8:
        base += 6.0
    if day >= 9 and hp <= 5:
        base += 10.0

    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0 and hp > 3 and no_water_days == 0:
        soft_cap = min(soft_cap, max(25.0, budget - reserve_days * 18.0))

    bid = min(base, budget, soft_cap)

    if hp <= 2 or no_water_days >= 2:
        bid = min(max(bid, min(budget, 95.0)), budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 1))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', True):
            alive_opps.append((opp_id, opp))

    # If no one is alive, conserve.
    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer aggressiveness.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base pressure estimate from yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Detect likely free-rider behavior (0 bid yesterday).
    had_zero_bid = any(abs(b) < 1e-9 for b in prev_bids)

    # Supply factor: when supply is higher, winning water is cheaper in strategy terms; bid less.
    # Normalize supply to [0,1].
    if MAX_SUPPLY - MIN_SUPPLY <= 0:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Urgency: if low HP or accumulating no-water days, increase bid.
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    else:
        urgency = 0.4
    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Target bid: aim to beat free-riders and avoid full matching of top aggressor.
    # If yesterday top bid was very high, assume someone like Eric will pressure again.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Bid enough to compete but not the maximum.
        target = min(DAILY_SALARY * (0.65 + 0.25 * urgency), highest_prev_bid - 5.0)
    else:
        # Lower pressure environment.
        target = DAILY_SALARY * (0.5 + 0.25 * urgency)

    # If we saw someone bidding 0 yesterday, they likely still underbid; reduce a bit.
    if had_zero_bid:
        target *= 0.9

    # Adjust with supply: higher supply => bid slightly less.
    target *= (1.05 - 0.1 * supply_norm)

    # Ensure within budget and non-negative.
    if budget <= 0.0:
        return 0.0

    # Cap bid to a fraction of budget to survive longer.
    max_affordable = min(budget, DAILY_SALARY * (0.95 if urgency >= 0.8 else 0.75))
    bid = float(max(0.0, min(target, max_affordable)))

    # If we are very urgent, allow more of budget but still not exceed DAILY_SALARY.
    if urgency >= 0.8:
        bid = float(min(budget, max(bid, DAILY_SALARY * 0.85)))

    # Final safety: bid cannot exceed budget.
    if bid > budget:
        bid = float(budget)

    return bid

