def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    num_water_slots = int(current_supply // WATER_REQ)

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    yesterday_bids_all = []
    strong_opponents_yesterday_bids = []

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            prev_trace = opp.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                yesterday_bids_all.append(prev_trace['bid'])
                if opp_id in ["Alex", "Eric"]:
                    strong_opponents_yesterday_bids.append(prev_trace['bid'])

    highest_prev_bid_overall = 0
    if yesterday_bids_all:
        highest_prev_bid_overall = max(yesterday_bids_all)

    highest_strong_opp_prev_bid = 0
    if strong_opponents_yesterday_bids:
        highest_strong_opp_prev_bid = max(strong_opponents_yesterday_bids)

    bid_amount = DAILY_SALARY * 0.6

    if my_hp <= 2 or my_no_water_days >= 1:
        target_bid = max(DAILY_SALARY * 1.5, highest_strong_opp_prev_bid + 10 if highest_strong_opp_prev_bid > 0 else DAILY_SALARY * 1.2)
        bid_amount = target_bid

    elif num_water_slots <= num_alive_opponents + 1:
        if highest_strong_opp_prev_bid > DAILY_SALARY * 0.9:
            bid_amount = highest_strong_opp_prev_bid + (DAILY_SALARY * 0.1)
        elif highest_prev_bid_overall > DAILY_SALARY * 0.7:
            bid_amount = highest_prev_bid_overall + (DAILY_SALARY * 0.05)
        else:
            bid_amount = DAILY_SALARY * 1.0

        if my_hp <= 5:
            bid_amount = bid_amount * 1.1
        elif my_hp > 7:
            bid_amount = bid_amount * 0.9

    else:
        if highest_strong_opp_prev_bid > DAILY_SALARY * 0.8:
            bid_amount = max(DAILY_SALARY * 0.7, highest_strong_opp_prev_bid * 0.95)
        elif highest_prev_bid_overall > DAILY_SALARY * 0.6:
            bid_amount = max(DAILY_SALARY * 0.6, highest_prev_bid_overall * 0.9)
        else:
            bid_amount = DAILY_SALARY * 0.5

    final_bid = min(my_budget, bid_amount)
    final_bid = max(1.0, final_bid)

    return final_bid
